// Writes cabac_tables.h from the helper's CABAC tables (app/service/stitchx/cabac-tables.json, ITU-T H.264 9.3).
const fs = require('fs'), path = require('path');
const t = JSON.parse(fs.readFileSync(path.join(__dirname, '../../app/service/stitchx/cabac-tables.json'), 'utf8'));
const mn = (list) => list.map(([m, n]) => `{${m},${n}}`).join(',');
fs.writeFileSync(path.join(__dirname, 'cabac_tables.h'), [
  '/* CABAC tables of ITU-T H.264 (9.3.1.1 init m,n for ctxIdx 0..459; 9.3.3.2 rangeTabLPS, transIdx). Generated by tables.js. */',
  `static const unsigned char LPS_RANGE[64][4] = {${t.rangeTabLPS.map((r) => `{${r.join(',')}}`).join(',')}};`,
  `static const unsigned char TRANS_LPS[64] = {${t.transIdxLPS.join(',')}};`,
  `static const unsigned char TRANS_MPS[64] = {${t.transIdxMPS.join(',')}};`,
  `static const signed char INIT_I[460][2] = {${mn(t.initI)}};`,
  `static const signed char INIT_PB[3][460][2] = {${t.initPB.map((x) => `{${mn(x)}}`).join(',')}};`,
  ''].join('\n'));
